50	+/* ============================ Lái xe: vật cản thu từ cảnh đã dựng ============================
51	+   Tách khỏi solids.ts vì cần module cảnh (environment/riverfront kéo core/renderer, core/materials vẽ canvas lúc import): test node
52	+   chỉ import solids.ts. Gọi MỘT lần, lần đầu vào chế độ lái (sau mọi bước dọn nhà): chỉ đọc cảnh, không đụng chuỗi rand() hay thứ tự dựng.
53	+   - Nhà đang hiện của khu phố (collectBuildings: level gần của THREE.LOD, bỏ instance scale 0) và nhà quanh Thuận Phước (InstancedMesh
54	+     thường của site.ts, tọa độ cục bộ group cầu): khối hộp thẳng trục từ chân tới mái.
55	+   - Chân đế địa danh và pano ven sông (riverfront footprints): là hình chữ nhật dọn nhà đã nới rộng 2–9 m mỗi phía và không có chiều cao,
56	+     nên phần lấn ô đường bị cắt bỏ (giữ mảnh lớn nhất còn lại), cao CONFIG.drive.solids.footTop.
57	+   - Chỉ giữ vật cách mép ô gần nhất ≤ CONFIG.drive.solids.near (cho thân xe và camera); xa hơn xe không bao giờ tới.
58	+   Nhà lấn ô đường thì vẫn thêm (đúng là có nhà trên đường) và đếm vào drSceneStats.intrude để test trình duyệt / người làm thấy. */
59	+import * as THREE from 'three';
60	+import { CONFIG } from '../../config';
61	+import { collectBuildings, type Rect } from '../../environment/riverfront/clearance';
62	+import { getRiverfront } from '../../environment/riverfront';
63	+import { drAddSolids, type DrNet, type DrPad, type DrSolid } from './net';
64	+
65	+export const drSceneStats = { buildings: 0, tpHouses: 0, footprints: 0, intrude: 0, skipped: 0 };
66	+
67	+const _m = new THREE.Matrix4(), _p = new THREE.Vector3(), _q = new THREE.Quaternion(), _s = new THREE.Vector3();
68	+const drGood = (r: Rect): boolean => [r.x0, r.x1, r.z0, r.z1].every(Number.isFinite) && r.x1 > r.x0 && r.z1 > r.z0;
69	+const drOverlap = (r: Rect, p: DrPad): boolean => r.x1 > p.x0 && r.x0 < p.x1 && r.z1 > p.z0 && r.z0 < p.z1;
70	+/* Khoảng cách mặt bằng nhỏ nhất từ r tới ô gần nhất (0 nếu chồng) */
71	+function drPadGap(pads: DrPad[], r: Rect): number {
72	+  let best = Infinity;
73	+  for (const p of pads) {
74	+    const dx = Math.max(0, p.x0 - r.x1, r.x0 - p.x1), dz = Math.max(0, p.z0 - r.z1, r.z0 - p.z1);
75	+    best = Math.min(best, Math.hypot(dx, dz));
76	+  }
77	+  return best;
78	+}
79	+/* Cắt khỏi r phần chồng lên các ô: mỗi lần chồng giữ mảnh lớn nhất trong bốn mảnh trái / phải / trước / sau; null nếu không còn gì */
80	+function drTrim(pads: DrPad[], r: Rect): Rect | null {
81	+  let cur: Rect = { ...r };
82	+  for (const p of pads) {
83	+    if (!drOverlap(cur, p)) continue;
84	+    const parts: Rect[] = [
85	+      { ...cur, x1: Math.min(cur.x1, p.x0) }, { ...cur, x0: Math.max(cur.x0, p.x1) },
86	+      { ...cur, z1: Math.min(cur.z1, p.z0) }, { ...cur, z0: Math.max(cur.z0, p.z1) }
87	+    ].filter(drGood);
88	+    if (!parts.length) return null;
89	+    cur = parts.reduce((a, b) => ((b.x1 - b.x0) * (b.z1 - b.z0) > (a.x1 - a.x0) * (a.z1 - a.z0) ? b : a));
90	+  }
91	+  return cur;
92	+}
93	+
94	+/* Thêm nhà đang hiện + chân đế địa danh gần ô đường vào net; trả số vật cản đã thêm */
95	+export function drCollectRuntime(net: DrNet, tpHouses: THREE.InstancedMesh | null): number {
96	+  const C = CONFIG.drive.solids, LAND = CONFIG.landY, pads = net.pads, out: DrSolid[] = [];
97	+  const st = { buildings: 0, tpHouses: 0, footprints: 0, intrude: 0, skipped: 0 };
98	+  const box = (r: Rect, y0: number, y1: number): boolean => {
99	+    if (!drGood(r) || !Number.isFinite(y0) || !Number.isFinite(y1) || y1 <= y0) { st.skipped++; return false; }
100	+    const gap = drPadGap(pads, r);
101	+    if (gap > C.near) return false;
102	+    if (gap === 0 && pads.some((p) => drOverlap(r, p))) st.intrude++;
103	+    out.push({ kind: 'rect', x0: r.x0, x1: r.x1, z0: r.z0, z1: r.z1, y0, y1 });
104	+    return true;
105	+  };
106	+  for (const b of collectBuildings()) {                             // collectBuildings đã cập nhật matrixWorld của cảnh; nhà khu phố đặt chân ở landY (city.ts)
107	+    if (box({ x0: b.x - b.w / 2, x1: b.x + b.w / 2, z0: b.z - b.d / 2, z1: b.z + b.d / 2 }, LAND, LAND + b.h)) st.buildings++;
108	+  }
109	+  if (tpHouses) {
110	+    tpHouses.updateWorldMatrix(true, false);
111	+    for (let i = 0; i < tpHouses.count; i++) {
112	+      tpHouses.getMatrixAt(i, _m); _m.decompose(_p, _q, _s);
113	+      if (_s.x < 1e-6) continue;                                    // nhà đã dọn khỏi đường mới (drClearRoads)
114	+      _p.applyMatrix4(tpHouses.matrixWorld);                         // hộp gốc ở chân (site.ts: BoxGeometry dời lên 0,5)
115	+      if (box({ x0: _p.x - _s.x / 2, x1: _p.x + _s.x / 2, z0: _p.z - _s.z / 2, z1: _p.z + _s.z / 2 }, _p.y, _p.y + _s.y)) st.tpHouses++;
116	+    }
117	+  }
118	+  for (const f of getRiverfront()?.footprints ?? []) {
119	+    if (!drGood(f)) { st.skipped++; continue; }
120	+    const r = drTrim(pads, f);
121	+    if (r && box(r, LAND, LAND + C.footTop)) st.footprints++;
122	+  }
123	+  if (st.skipped) console.warn(`[drive] bỏ ${st.skipped} vật cản hỏng khi thu từ cảnh`);
124	+  if (st.intrude) console.warn(`[drive] ${st.intrude} nhà lấn ô đường`);
125	+  Object.assign(drSceneStats, st);
126	+  drAddSolids(net, out);
127	+  return out.length;
128	+}
