138	+   đường ven sông bên dưới và tường ống hầm không chặn đường phố bên trên. Nhà và chân đế địa danh thêm lúc chạy (sceneSolids.ts).
139	+   Luật (spec §6, plan Task 3):
140	+   - Mép ô đã là bó vỉa / dải giữa (xe không ra ngoài ô được) nên không dựng vật cản cho vỉa hay dải giữa đường; chỉ dựng thứ cao hơn
141	+     mặt đường ≥ 0,35 m nằm trong hoặc sát ô, và thứ camera sau xe có thể vướng (thân rồng, tháp, tường hầm).
142	+   - Gờ chắn bánh, lề bộ hành và lan can mỗi bên cầu gộp thành một vật cản "lề cầu" (mặt trong gờ chắn → mặt ngoài lan can, cao tới
143	+     đỉnh tay vịn): với thân xe tương đương gờ chắn (đỉnh 0,545 m đã chặn), với camera là xấp xỉ an toàn.
144	+   - Vật cản dọc mặt dốc chia đoạn (drAlongX) để cao độ trong mỗi đoạn lệch ≤ CONFIG.drive.solids.yTol.
145	+   - Kết cấu trên nhịp quay Cầu sông Hàn đứng yên ở vị trí đóng: khi cầu quay, cổng DR_GATE_SWING đã bỏ ô nhịp quay nên xe không tới đó.
146	+
147	+   Bảng nguồn số (file : hình học đã đọc; (ước lượng) = chọn ở đây):
148	+   | Vật | Hình học | Nguồn |
149	+   | Cầu Rồng: gờ chắn xe → lan can | |z| 15,9..18,72, cao 1,22 trên deckY, |x| ≤ 333 | dragon/deck.ts:13-28 (gờ 0,35 × 0,9; tay vịn hw − 0,1 dày 0,14; LED tới 1,215) |
150	+   | Thân rồng | đường tim stSpinePoints, bán kính 1,03 r + 0,085 | dragon/body.ts:15-20,27-39,49; stroll/mapData.ts |
151	+   | Dây treo dưới bụng rồng | chân dây |z| = 2,8, bán kính 0,11, khi bụng cách dải giữa ≥ 2,5 m, |x| < 255 | dragon/body.ts:140-151 |
152	+   | Trụ nhịp dẫn Cầu Rồng | x = −294, z = ±8,5, bán trục 2,0 × 2,8, tới đáy bản mặt cầu deckY − 0,5 | dragon/deck.ts:47-56; config.ts approachPiers |
153	+   | Lề cầu chung (common/deck.ts) | gờ chắn tâm hw − lề + 0,12 rộng 0,25 cao 0,545; tay vịn hw − 0,15 dày 0,12 đỉnh 1,245 | common/deck.ts:9-18 |
154	+   | Cầu sông Hàn | lề cầu |x| ≤ 288,5 (cố định + nhịp quay; vẽ tới 290, cắt ở mép làn đường ven sông); cột đôi x ±0,45 |dz| ≤ 1,0 cao 38; chân chữ A (±15, +0,2) → (0, +19) tiết diện 1,0 × 1,4; dây văng neo dầm (x 20..59,2, +0,35) → cột (±0,5, +25..36,5); hộp barie 0,45 × 0,45 cao 1,0 tại (±68,35, ±4,6) | fixedSpans.ts:64; swingSpan.ts:38-55; signals.ts:10-17 |
155	+   | Trần Thị Lý | lề cầu x −470..450; tháp nghiêng ttlPylonPoint lấy mẫu quanh mặt cầu, |dz| ≤ Wz / 2 = 2,5; trụ trên bờ x ±1,3 |dz| ≤ 9,5 tới đáy dầm | tran-thi-ly/deck.ts:16,32; pylon.ts; approaches.ts:12-15 |
156	+   | Thuận Phước | lề cầu |x| ≤ 1 047,5; tháp (mặt trong ≥ 11,4) và buồng neo (≥ 9,5) cách mép làn 7,5 hơn 1 m: không dựng | thuan-phuoc/deck.ts:39; towers.ts; approaches.ts:20-21 |
157	+   | Hầm, đoạn kín |x| ≤ 490 | tường ngoài |dz| 14,6..15,6 và khối giữa |dz| ≤ 2,1 (tường + hành lang) từ mặt đường tới nóc + 7,0 | han-tunnel/shell.ts:22-30; config.ts hanTunnel |
158	+   | Hầm, đoạn hở 490..697,5 | tường ngoài tới wallTop = max(đường + 1,1, mặt đất + 0,6); dải giữa |dz| ≤ 2,1 cao 0,9 | han-tunnel/outdoor.ts:19,38-40 |
159	+   ============================================================================================================ */
160	+import { CONFIG } from '../../config';
161	+import { deckY } from '../../bridges/dragon/profile';
162	+import { SH, shRoadY } from '../../bridges/song-han/profile';
163	+import { TTL, ttlRoadY, ttlPylonSection, ttlPylonPoint } from '../../bridges/tran-thi-ly/profile';
164	+import { TP, tpRoadY } from '../../bridges/thuan-phuoc/profile';
165	+import { HR, hrRoadY } from '../../bridges/han-tunnel/profile';
166	+import { stSpinePoints, stSpinePoint } from '../stroll/mapData';
167	+import type { DrSolid } from './net';
168	+
169	+/* Hai barie Cầu sông Hàn (Tây / Đông nhịp quay): tên dùng cho hiển thị và sơ tán (Task 8). Hộp barie là vật cản tĩnh; tay barie không:
170	+   khi cầu quay, ô nhịp quay đã bị cổng DR_GATE_SWING bỏ khỏi mạng đường */
171	+export const DR_BARRIER_W = 'shBarrierW', DR_BARRIER_E = 'shBarrierE';
172	+export const DR_BARRIER_X: Record<string, number> = { [DR_BARRIER_W]: -SH.barrierX, [DR_BARRIER_E]: SH.barrierX };
173	+
174	+type DrF = (x: number) => number;
175	+const TOL = CONFIG.drive.solids.yTol, LAND = CONFIG.landY;
176	+
177	+/* Vật cản chữ nhật dọc trục X trên mặt dốc: chia đoạn (bước ≤ 1 m) sao cho lo(x) và hi(x) trong mỗi đoạn lệch ≤ TOL; y0 = min lo, y1 = max hi */
178	+function drAlongX(out: DrSolid[], x0: number, x1: number, z0: number, z1: number, lo: DrF, hi: DrF): void {
179	+  const n = Math.max(1, Math.ceil(x1 - x0)), dx = (x1 - x0) / n;
180	+  let a = x0, l0 = lo(x0), l1 = l0, h0 = hi(x0), h1 = h0;
181	+  for (let i = 1; i <= n; i++) {
182	+    const x = x0 + dx * i, l = lo(x), h = hi(x);
183	+    if (Math.max(l1, l) - Math.min(l0, l) > TOL || Math.max(h1, h) - Math.min(h0, h) > TOL) {
184	+      const xp = x - dx;                                            // đóng đoạn tại điểm trước, đoạn mới bắt đầu từ đó
185	+      if (xp > a + 1e-9) {
186	+        out.push({ kind: 'rect', x0: a, x1: xp, z0, z1, y0: l0, y1: h1 });
187	+        a = xp; l0 = l1 = lo(xp); h0 = h1 = hi(xp);
188	+      }
189	+    }
190	+    l0 = Math.min(l0, l); l1 = Math.max(l1, l); h0 = Math.min(h0, h); h1 = Math.max(h1, h);
191	+  }
192	+  out.push({ kind: 'rect', x0: a, x1: x1, z0, z1, y0: l0, y1: h1 });
193	+}
194	+/* Lề cầu hai bên (gờ chắn bánh + lề + lan can) của cầu dựng bằng common/deck.ts addDeckEdges */
195	+function drDeckEdges(out: DrSolid[], zc: number, inner: number, outer: number, top: number, x0: number, x1: number, prof: DrF): void {
196	+  for (const s of [-1, 1]) drAlongX(out, x0, x1, s < 0 ? zc - outer : zc + inner, s < 0 ? zc - inner : zc + outer, prof, (x) => prof(x) + top);
197	+}
198	+const CD_TOP = 1.245;                                               // m — đỉnh tay vịn common/deck.ts (1,2 + 0,09 / 2)
199	+const cdInner = (hw: number, sidewalk: number) => hw - sidewalk + 0.12 - 0.125;   // mặt trong gờ chắn bánh
200	+const cdOuter = (hw: number) => hw - 0.15 + 0.06;                   // mặt ngoài tay vịn
201	+
202	+/* ===== Cầu Rồng ===== */
203	+const DR_X = CONFIG.length / 2;                                     // 333
204	+const DR_IN = CONFIG.median / 2 + CONFIG.lanesPerDir * CONFIG.laneWidth + CONFIG.shoulder - 0.35;   // 15,9 — mặt trong gờ chắn xe
205	+const DR_OUT = CONFIG.width / 2 - 0.1 + 0.07;                       // 18,72 — mặt ngoài tay vịn
206	+const DR_TOP = 1.22;                                                // m — đỉnh dải LED trên tay vịn (1,19 + 0,025, làm tròn lên)
