+});
+
+test('trụ Cầu Rồng trên Bạch Đằng có mặt, không vật cản nào trong ô nhánh rẽ', () => {
+  for (const z of [-8.5, 8.5]) assert.ok(hits(-294, z, CONFIG.roadY + 1).length > 0, `trụ z = ${z}`);
+  const slips = pads.filter((p) => p.kind === 'slip');
