+});
+
+test('không vật cản nào lấn ô cùng tầng quá 0,1 m', () => {
+  /* cho phép: gờ chắn bánh lấn 0,005 m, hộp barie Cầu sông Hàn lấn làn 0,075 m (đúng hình vẽ) */
+  for (const p of pads) for (const s of solids) {
